SELECT DATE_TRUNC('MONTH', starts_on) AS activity_month, DATE_TRUNC('QUARTER', starts_on) AS quarter_start, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, MIN(discount_pct) AS min_discount_pct, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes, COUNT(*) AS event_count FROM promotions GROUP BY CUBE (DATE_TRUNC('MONTH', starts_on), DATE_TRUNC('QUARTER', starts_on)) ORDER BY discount_pct_stddev NULLS LAST
